const rawFilters = $('Get Active Filters').all().map(i => i.json);
const activeFilters = rawFilters.filter(f => f.is_active === true);

const targets = $('Generate Scrape Targets').all();
const responses = $('Fetch Target Page').all();

const allProducts = [];

for (let idx = 0; idx < responses.length; idx++) {
  const target = targets[idx]?.json || {};
  const html = responses[idx]?.json?.data || responses[idx]?.json?.body || '';
  if (typeof html !== 'string' || html.length === 0) continue;

  try {
// 1. GamingGen
    if (target.site === 'gaming_gen_tr') {
      const sections = html.split(/<li[^>]*class="[^"]*product type-product/);
      for (let i = 1; i < sections.length; i++) {
        const section = sections[i];
        const inStock = !section.includes('outofstock');

        const urlMatch = section.match(/href="([^"]+)"/);
        const titleMatch = section.match(/<h2[^>]*class="[^"]*woocommerce-loop-product__title[^"]*"[^>]*>([^<]+)<\/h2>/);
        const priceMatch = section.match(/<ins[^>]*>[\s\S]*?<bdi>([\d\.,]+)&nbsp;<span class="woocommerce-Price-currencySymbol"[^>]*>/i) ||
                           section.match(/<span class="woocommerce-Price-amount amount">[\s\S]*?<bdi>([\d\.,]+)&nbsp;<span class="woocommerce-Price-currencySymbol"[^>]*>/i);
        const idMatch = section.match(/post-(\d+)/);

        if (urlMatch && titleMatch && priceMatch) {
          const url = urlMatch[1];
          let rawTitle = titleMatch[1].trim();
          const price = parseFloat(priceMatch[1].replace(/\./g, '').replace(',', '.'));
          const id = idMatch ? idMatch[1] : url.split('/').filter(Boolean).pop();
          const pid = 'gaming_gen_' + id;

          // Extract specs from list if present
          const specs = [...section.matchAll(/<span class="model">([^<]+)<\/span>/g)].map(m => m[1].trim());
          if (specs.length > 0) {
            rawTitle += ' (' + specs.join(' / ') + ')';
          }
          rawTitle = rawTitle.replace(/(\d+)(ti|super|xt)\b/gi, '$1 $2');

          if (!allProducts.some(x => x.product_id === pid)) {
            allProducts.push({
              product_id: pid,
              source_site: 'gaming_gen_tr',
              product_name: rawTitle,
              product_url: url,
              current_price: price,
              previous_price: price,
              in_stock: inStock
            });
          }
        }
      }
    }

    // 2. GameGaraj
    else if (target.site === 'gamegaraj') {
      const cards = html.split(/<div class="w-full p-6 hover:scale-105/);
      for (let i = 1; i < cards.length; i++) {
        const card = cards[i];
        const linkMatch = card.match(/href="(\/(?:oem-paketler|urun)\/([a-zA-Z0-9_\-]+)\/?)"/);
        const titleMatch = card.match(/title="([^"]+)"/);
        const priceMatch = card.match(/>([\d\.,]+)\s*TL<\/p>/i);

        if (linkMatch && titleMatch && priceMatch) {
          const url = 'https://www.gamegaraj.com' + linkMatch[1];
          const slug = linkMatch[2];
          const rawTitle = titleMatch[1].trim();
          const price = parseFloat(priceMatch[1].replace(/\./g, '').replace(',', '.'));
          const inStock = !card.includes('Tükendi') && !card.includes('Stokta Yok');

          const cpu = (card.match(/İşlemci:\s*([^<]+)/)?.[1] || '').trim();
          const gpu = (card.match(/Ekran Kartı:\s*([^<]+)/)?.[1] || '').trim();
          const ram = (card.match(/RAM:\s*([^<]+)/)?.[1] || '').trim();
          const ssd = (card.match(/SSD:\s*([^<]+)/)?.[1] || '').trim();

          const specParts = [cpu, gpu, ram, ssd].filter(Boolean);
          let fullTitle = rawTitle;
          if (specParts.length > 0) fullTitle += ' (' + specParts.join(' / ') + ')';
          fullTitle = fullTitle.replace(/(\d+)(ti|super|xt)\b/gi, '$1 $2');
          const pid = 'gamegaraj_' + slug;

          if (!allProducts.some(x => x.product_id === pid)) {
            allProducts.push({
              product_id: pid,
              source_site: 'gamegaraj',
              product_name: fullTitle,
              product_url: url,
              current_price: price,
              previous_price: price,
              in_stock: inStock
            });
          }
        }
      }
    }

    // 3. Itopya
    else if (target.site === 'itopya') {
      const cards = html.split(/<div class="product"/);
      for (let i = 1; i < cards.length; i++) {
        const card = cards[i];
        const linkMatch = card.match(/href="(\/(?:[^"]+)_h(\d+))"/);
        const titleMatch = card.match(/<h2[^>]*class="eseoContainer"[^>]*>([^<]+)<\/h2>/i) ||
                           card.match(/alt="([^"]+)"/i);
        const priceMatch = card.match(/class="product-price"[\s\S]*?<strong>([\d\.,]+)\s*<abbr/i);

        if (linkMatch && titleMatch && priceMatch) {
          const url = 'https://www.itopya.com' + linkMatch[1];
          const id = linkMatch[2];
          let rawTitle = titleMatch[1].trim();
          const price = parseFloat(priceMatch[1].replace(/\./g, '').replace(',', '.'));
          const inStock = !card.includes('Tükendi') && !card.includes('Stokta Yok');

          rawTitle = rawTitle.replace(/(\d+)(ti|super|xt)\b/gi, '$1 $2');
          const pid = 'itopya_' + id;

          if (!allProducts.some(x => x.product_id === pid)) {
            allProducts.push({
              product_id: pid,
              source_site: 'itopya',
              product_name: rawTitle,
              product_url: url,
              current_price: price,
              previous_price: price,
              in_stock: inStock
            });
          }
        }
      }
    }

    // 4. PcKolik
    else if (target.site === 'pckolik') {
      let systems = [];

      // Primary: Next.js embedded JSON payload (systems array)
      const escIdx = html.indexOf('\\"systems\\":[');
      const plainIdx = html.indexOf('"systems":[');
      const isEscaped = escIdx !== -1;
      const startIdx = isEscaped ? escIdx + '\\"systems\\":'.length : (plainIdx !== -1 ? plainIdx + '"systems":'.length : -1);

      if (startIdx !== -1) {
        let bracketCount = 0;
        let started = false;
        let endIdx = -1;
        for (let i = startIdx; i < html.length; i++) {
          if (html[i] === '[') {
            bracketCount++;
            started = true;
          } else if (html[i] === ']') {
            bracketCount--;
            if (started && bracketCount === 0) {
              endIdx = i;
              break;
            }
          }
        }

        if (endIdx !== -1) {
          const rawSlice = html.slice(startIdx, endIdx + 1);
          const jsonStr = isEscaped ? rawSlice.replace(/\\"/g, '"').replace(/\\\\/g, '\\') : rawSlice;
          try {
            systems = JSON.parse(jsonStr);
          } catch (e) {
            console.error('Failed to parse PcKolik systems JSON:', e.message);
          }
        }
      }

      if (Array.isArray(systems) && systems.length > 0) {
        for (const item of systems) {
          if (!item.id || !item.name) continue;

          const pid = 'pckolik_' + item.id;
          const url = 'https://pckolik.com.tr/hazir-sistem/' + (item.slug || item.id);
          const price = Number(item.price) || 0;
          const inStock = Boolean(item.inStock);

          const specs = Array.isArray(item.specs) ? item.specs : [];
          const cpu = specs.find(s => s.icon === 'cpu')?.label || item.facetler?.cpuSeri || '';
          const gpu = specs.find(s => s.icon === 'gpu')?.label || item.facetler?.gpuModel || '';
          const ram = specs.find(s => s.icon === 'ram')?.label || item.facetler?.ramTipi || '';
          const ssd = specs.find(s => s.icon === 'ssd')?.label || '';

          const specParts = [cpu, gpu, ram, ssd].filter(Boolean);
          let fullTitle = item.name;
          if (specParts.length > 0) {
            fullTitle += ' (' + specParts.join(' / ') + ')';
          }
          fullTitle = fullTitle.replace(/(\d+)(ti|super|xt)\b/gi, '$1 $2');

          if (!allProducts.some(x => x.product_id === pid)) {
            allProducts.push({
              product_id: pid,
              source_site: 'pckolik',
              product_name: fullTitle,
              product_url: url,
              current_price: price,
              previous_price: price,
              in_stock: inStock
            });
          }
        }
      } else {
        // Fallback: strictly bounded card containers (prevents attribute bleed across cards)
        const cardChunks = html.split(/<div class="[^"]*rounded-xl border border-line[^"]*">/);
        for (let i = 1; i < cardChunks.length; i++) {
          const chunk = cardChunks[i];
          const urlMatch = chunk.match(/href="(\/hazir-sistem\/[^"]+--([a-zA-Z0-9]+))"/);
          const titleMatch = chunk.match(/<h3[^>]*>([^<]+)<\/h3>/);
          const priceMatch = chunk.match(/class="price-now[^"]*"[^>]*>([\d\.,]+)/);

          if (urlMatch && titleMatch && priceMatch) {
            const url = 'https://pckolik.com.tr' + urlMatch[1];
            const id = urlMatch[2];
            const rawTitle = titleMatch[1].trim();
            const price = parseFloat(priceMatch[1].replace(/\./g, '').replace(',', '.'));
            const inStock = !chunk.includes('Tükendi') && !chunk.includes('Stokta Yok');
            const pid = 'pckolik_' + id;

            if (!allProducts.some(x => x.product_id === pid)) {
              allProducts.push({
                product_id: pid,
                source_site: 'pckolik',
                product_name: rawTitle,
                product_url: url,
                current_price: price,
                previous_price: price,
                in_stock: inStock
              });
            }
          }
        }
      }
    }

    // 5. Vatan Bilgisayar
    else if (target.site === 'vatan') {
      const regex = /<div class="product-list__content">[\s\S]*?<a[^>]*href="([^"]+)"[\s\S]*?<h3>([^<]+)<\/h3>[\s\S]*?class="product-list__price">([\d\.,]+)/g;
      let m;
      while ((m = regex.exec(html)) !== null) {
        const url = m[1].startsWith('http') ? m[1] : ('https://www.vatanbilgisayar.com' + m[1]);
        const rawTitle = m[2].trim();
        const price = parseFloat(m[3].replace(/\./g, '').replace(',', '.'));
        const id = url.split('/').pop().replace('.html', '');
        const block = html.slice(m.index, m.index + 1200);
        const inStock = !block.includes('Tükendi') && !block.includes('Stokta Yok');
        const pid = 'vatan_' + id;

        if (!allProducts.some(x => x.product_id === pid)) {
          allProducts.push({
            product_id: pid,
            source_site: 'vatan',
            product_name: rawTitle,
            product_url: url,
            current_price: price,
            previous_price: price,
            in_stock: inStock
          });
        }
      }
    }

    // 6. MediaMarkt
    else if (target.site === 'mediamarkt') {
      const ldMatches = html.match(/<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/gi) || [];
      for (const scriptTag of ldMatches) {
        const jsonText = scriptTag.replace(/<script[^>]*>/, '').replace(/<\/script>/, '');
        try {
          const data = JSON.parse(jsonText);
          if (data['@type'] === 'ItemList' && Array.isArray(data.itemListElement)) {
            for (const li of data.itemListElement) {
              const item = li.item;
              if (!item || !item.name || !item.url) continue;
              let rawTitle = item.name.trim();
              rawTitle = rawTitle.replace(/(\d+)(ti|super|xt)\b/gi, '$1 $2');
              const price = Number(item.offers?.price) || 0;
              const url = item.url;
              const id = url.split('-').pop().replace('.html', '');
              const pid = 'mediamarkt_' + id;

              if (!allProducts.some(x => x.product_id === pid)) {
                allProducts.push({
                  product_id: pid,
                  source_site: 'mediamarkt',
                  product_name: rawTitle,
                  product_url: url,
                  current_price: price,
                  previous_price: price,
                  in_stock: true
                });
              }
            }
          }
        } catch (e) {}
      }
    }
  } catch (err) {
    console.error(`Error parsing site ${target.site} page ${target.page}:`, err.message);
  }
}

// Helper: check if product matches filter
function matchesFilter(product, filter) {
  const name = product.product_name.toLowerCase();

  if (filter.source_site && filter.source_site !== 'all' && filter.source_site !== product.source_site) {
    return false;
  }

  if (filter.min_price && product.current_price < filter.min_price) return false;
  if (filter.max_price && product.current_price > filter.max_price) return false;

  // Exclude keywords
  if (filter.exclude_keywords) {
    const excludes = filter.exclude_keywords.split(/[,+]/).map(s => s.trim().toLowerCase()).filter(Boolean);
    for (const ex of excludes) {
      if (name.includes(ex)) return false;
    }
  }

  // Include keywords: ALL specified keywords must match (AND logic)
  if (filter.include_keywords) {
    let includes = [];
    if (filter.include_keywords.includes(',')) {
      includes = filter.include_keywords.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
    } else if (filter.include_keywords.includes('+')) {
      includes = filter.include_keywords.split('+').map(s => s.trim().toLowerCase()).filter(Boolean);
    } else {
      includes = filter.include_keywords.split(/\s+/).map(s => s.trim().toLowerCase()).filter(Boolean);
    }

    const includesTi = includes.some(k => /\bti\b/i.test(k));
    const includesSuper = includes.some(k => /\bsuper\b/i.test(k));
    const includesXt = includes.some(k => /\bxt\b/i.test(k));

    for (const inc of includes) {
      const isModelNumber = /^\d{4}$/.test(inc);
      let pattern;
      if (isModelNumber) {
        const forbidden = [];
        if (!includesTi) forbidden.push('ti');
        if (!includesSuper) forbidden.push('super');
        if (!includesXt) forbidden.push('xt');

        if (forbidden.length > 0) {
          pattern = new RegExp('\\b' + inc + '\\b(?!\\s*(?:' + forbidden.join('|') + '))', 'i');
        } else {
          pattern = new RegExp('\\b' + inc + '\\b', 'i');
        }
      } else {
        const procMatch = inc.match(/^(\d{4,5})([a-zA-Z]+)$/);
        if (procMatch) {
          pattern = new RegExp('\\b' + procMatch[1] + '\\s*' + procMatch[2] + '\\b', 'i');
        } else {
          pattern = new RegExp('\\b' + inc.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i');
        }
      }

      if (!pattern.test(name)) return false;
    }
  }

  return true;
}

// Tag products with all matching filters
const outputItems = [];
for (const product of allProducts) {
  const matchedFilters = [];
  for (const filter of activeFilters) {
    if (matchesFilter(product, filter)) {
      matchedFilters.push({
        id: filter.id,
        drop_threshold_percent: filter.drop_threshold_percent || 5,
        notify_dm: Boolean(filter.notify_dm || false),
        discord_user_id: String(filter.discord_user_id || '')
      });
    }
  }

  outputItems.push({
    ...product,
    matched_filters: matchedFilters,
    is_filter_matched: matchedFilters.length > 0,
    drop_threshold_percent: matchedFilters.length > 0 ? Math.min(...matchedFilters.map(f => f.drop_threshold_percent)) : 5
  });
}

return outputItems.map(item => ({ json: item }));

const GRAPH_DAY = 86400000;
function graphLocalDay(value) {
  const time = new Date(value).getTime();
  if (!Number.isFinite(time)) throw new Error('Invalid graph observation timestamp');
  return new Date(time + 3 * 3600000).toISOString().slice(0, 10);
}
function graphWeek(day) {
  const date = new Date(day + 'T00:00:00Z');
  date.setUTCDate(date.getUTCDate() - (date.getUTCDay() + 6) % 7);
  return date.toISOString().slice(0, 10);
}
function graphDayShift(day, amount) {
  return new Date(new Date(day + 'T00:00:00Z').getTime() + amount * GRAPH_DAY).toISOString().slice(0, 10);
}
function readGraphHistory(raw) {
  if (!raw) return {version: 1, daily: [], weekly: [], monthly: []};
  const history = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (history.version !== 1 || !['daily', 'weekly', 'monthly'].every(key => Array.isArray(history[key]))) {
    throw new Error('Invalid stored chart_history');
  }
  for (const key of ['daily', 'weekly', 'monthly']) {
    for (const point of history[key]) {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(point.day) || !Number.isFinite(point.price) || point.price <= 0 || !Number.isFinite(Date.parse(point.observed_at))) {
        throw new Error('Invalid stored price point');
      }
    }
  }
  return JSON.parse(JSON.stringify(history));
}
function addGraphObservation(raw, product, timestamp, reset = false) {
  const previous = readGraphHistory(raw);
  const history = reset ? readGraphHistory(null) : previous;
  if (reset && previous.monthly.length) {
    history.archived = [...(previous.archived || []), {monthly: previous.monthly}];
  }
  const day = graphLocalDay(timestamp);
  const week = graphWeek(day);
  const month = day.slice(0, 7) + '-01';
  history.daily = history.daily.filter(point => point.day >= graphDayShift(day, -6));
  history.weekly = history.weekly.filter(point => point.day >= graphWeek(graphDayShift(day, -30)));
  const price = Number(product.current_price);
  if (product.in_stock === true && Number.isFinite(price) && price > 0) {
    for (const [key, bucket] of [['daily', day], ['weekly', week], ['monthly', month]]) {
      const existing = history[key].find(point => point.day === bucket);
      const rounded = Math.round(price * 100) / 100;
      if (existing && (rounded < existing.price || (rounded === existing.price && timestamp < existing.observed_at))) {
        existing.price = rounded;
        existing.observed_at = timestamp;
      } else if (!existing) history[key].push({day: bucket, price: rounded, observed_at: timestamp});
      history[key].sort((a, b) => a.day.localeCompare(b.day));
    }
  }
  return JSON.stringify(history);
}
function graphSeries(raw, period, timestamp) {
  const history = readGraphHistory(raw);
  const today = graphLocalDay(timestamp);
  let buckets;
  let points;
  if (period === 'week') {
    buckets = Array.from({length: 7}, (_, i) => graphDayShift(today, i - 6));
    points = history.daily;
  } else if (period === 'month') {
    const start = graphWeek(graphDayShift(today, -30));
    buckets = [];
    for (let day = start; day <= today; day = graphDayShift(day, 7)) buckets.push(day);
    points = history.weekly;
  } else if (period === 'year' || period === 'max') {
    const first = period === 'year'
      ? new Date(Date.UTC(Number(today.slice(0, 4)), Number(today.slice(5, 7)) - 12, 1)).toISOString().slice(0, 10)
      : (history.monthly[0]?.day || today.slice(0, 7) + '-01');
    buckets = [];
    for (let day = first; day <= today;) {
      buckets.push(day);
      const date = new Date(day + 'T00:00:00Z');
      date.setUTCMonth(date.getUTCMonth() + 1);
      day = date.toISOString().slice(0, 10);
    }
    points = history.monthly;
  } else throw new Error('Invalid graph period');
  const byDay = new Map(points.map(point => [point.day, point.price]));
  const included = points.filter(point => buckets.includes(point.day));
  const minimum = included.slice().sort((a, b) => a.price - b.price || a.observed_at.localeCompare(b.observed_at))[0] || null;
  return {labels: buckets.map(day => period === 'week' || period === 'month' ? day : day.slice(0, 7)), values: buckets.map(day => byDay.get(day) ?? null), minimum};
}
function priceChartConfig(raw, period, timestamp) {
  const series = graphSeries(raw, period, timestamp);
  const titles = {week: '1 Hafta · Günlük En Düşük Fiyat', month: '1 Ay · Haftalık En Düşük Fiyat', year: '1 Yıl · Aylık En Düşük Fiyat', max: 'Max · Aylık En Düşük Fiyat'};
  const caption = series.minimum ? 'En düşük: ' + series.minimum.price.toLocaleString('tr-TR') + ' TL · ' + graphLocalDay(series.minimum.observed_at) : 'Bu dönem için kayıtlı fiyat yok';
  return {type: 'line', data: {labels: series.labels, datasets: [{label: 'En düşük fiyat (TL)', data: series.values, borderColor: '#4f8cff', backgroundColor: '#4f8cff', fill: false, tension: 0, spanGaps: false, pointRadius: 4}]}, options: {plugins: {title: {display: true, text: titles[period]}, subtitle: {display: true, position: 'bottom', text: caption, padding: 12}, legend: {display: false}}, scales: {y: {beginAtZero: false, title: {display: true, text: 'TL'}}}}};
}



const historyRows = $('Get Price History').all().map(i => i.json);
const historyMap = new Map();
for (const row of historyRows) {
  if (row.product_id) {
    historyMap.set(row.product_id, row);
  }
}

const siteLabels = {
  gaming_gen_tr: 'Gaming.gen.tr',
  gamegaraj: 'GameGaraj',
  itopya: 'İtopya',
  pckolik: 'PcKolik',
  vatan: 'Vatan Bilgisayar',
  mediamarkt: 'MediaMarkt'
};

const results = [];
const graphNow = new Date().toISOString();
const graphState = new Map();

for (const item of $input.all()) {
  const p = item.json;
  const history = historyMap.get(p.product_id);

  let graphReset = false;
  let previousPrice = p.previous_price || p.current_price;
  let dropPercent = 0;
  const notifications = [];

  if (history && history.current_price) {
    previousPrice = history.current_price;

    // Safety check 1: if base product name changed completely, the old row was mismatched or repurposed. Baseline it!
    const oldBase = (history.product_name || '').split('(')[0].trim().toLowerCase();
    const newBase = (p.product_name || '').split('(')[0].trim().toLowerCase();
    if (oldBase && newBase && !oldBase.includes(newBase) && !newBase.includes(oldBase)) {
      previousPrice = p.current_price;
      graphReset = true;
    }

    // Safety check 2: baseline any PcKolik records saved prior to 2026-10-29 13:40 UTC to prevent false discounts from corrupted regex history
    if (p.source_site === 'pckolik') {
      const rowTime = history.last_checked_at ? new Date(history.last_checked_at).getTime() : 0;
      if (rowTime < 1793281500000) {
        previousPrice = p.current_price;
      }
    }

    if (p.current_price < previousPrice) {
      dropPercent = ((previousPrice - p.current_price) / previousPrice) * 100;

      // Per AGENTS.md: Stokta olmayan ürünü indirim sayma.
      if (p.in_stock && p.matched_filters && p.matched_filters.length > 0) {
        for (const mf of p.matched_filters) {
          if (dropPercent >= mf.drop_threshold_percent) {
            const isDm = Boolean(mf.notify_dm && mf.discord_user_id);
            const safeTitle = p.product_name.length > 230 ? p.product_name.slice(0, 227) + '...' : p.product_name;
            const embed = {
              title: '🔥 FİYAT DÜŞÜŞÜ: ' + safeTitle,
              url: p.product_url,
              color: 3066993,
              fields: [
                {
                  name: '🏢 Kaynak Site',
                  value: siteLabels[p.source_site] || p.source_site,
                  inline: true
                },
                {
                  name: '📉 İndirim Oranı',
                  value: '%' + dropPercent.toFixed(1) + ' Düşüş',
                  inline: true
                },
                {
                  name: '📦 Stok Durumu',
                  value: p.in_stock ? 'Stokta Var ✅' : 'Tükendi ❌',
                  inline: true
                },
                {
                  name: '💰 Eski Fiyat',
                  value: previousPrice.toLocaleString('tr-TR') + ' ₺',
                  inline: true
                },
                {
                  name: '🏷️ Yeni Fiyat',
                  value: '**' + p.current_price.toLocaleString('tr-TR') + ' ₺**',
                  inline: true
                }
              ],
              footer: {
                text: 'n8n Fiyat Takip Sistemi • ' + (isDm ? 'Özel Bildirim (DM)' : 'Kanal Bildirimi')
              },
